@startuml

class Employee {
  + IdentifyingNumber : string
  + Name : string
  + Address : string
}

class PartAccessory {
  + Category : string
  + SerialNumber : string
  + Price : double
}

class Car {
  + LicensePlate : string
  + Make : string
  + Model : string
  + Color : string
}

class Owner {
  + Name : string
  + IdentifyingNumber : string
  + Address : string
  + Phone : string
}

class AssemblyService {
  + Kms : int
  + WorkHours : float
  + AdmissionDate : date
  + FinishDate : date
}

class CarModel {
  + ModelName : string
}

Employee "1" -- "*" AssemblyService : responsible for
AssemblyService "*" -- "1" Car : executed in
AssemblyService "*" -- "*" PartAccessory : fitted with
PartAccessory "*" -- "*" CarModel : fits in
Car "1" -- "1" Owner : owned by
Owner "1" -- "*" Car : owns

@enduml

